        // If opened via 1-Click Auto-Delete button (?adsops_auto_delete_passkey=1) or user clicked HUD delete
        if (url.includes("adsops_auto_delete_passkey=1") && !autoDeletePasskeyTriggered) {
          autoDeletePasskeyTriggered = true;
