        .filter((k) => Boolean(KA_STOPS[k]));
      const steps = rawRoute.length >= 2 ? rawRoute : pickFallbackKeepAliveSteps(viaTier, kaMode);
      const routeSummary = steps.map((k) => (KA_STOPS[k] ? KA_STOPS[k].label : k)).join(" → ");
      const localSession = {
