        createBtn.style.boxShadow = "0 0 18px rgba(16,185,129,0.75)";
        if (autoSubmit && autoSubmitBlockedReason) {
          setHudPageStatus(
            (batchStep ? "[Lô " + batchStep + "] " : "") +
              "🫧 [Khiên Bảo Vệ] " +
              autoSubmitBlockedReason +
              " — Đã điền sẵn nhưng khóa bấm Tạo Trang tự động!",
            "#fbbf24",
          );
          return;
