          setHudPageStatus((batchStep ? "[Lô " + batchStep + "] " : "") + "🌱 Đã tự điền chuẩn kỹ thuật! Kiểm tra 1s rồi bấm Tạo Trang", "#34d399");
          return;
        }

        const isDisabled = Boolean(createBtn.disabled) || createBtn.getAttribute("aria-disabled") === "true";
